operation.add:
		$this->load->language('extension/module/cyberpunks_shop_color_palettes');
		$data['cyberpunks_color_palettes'] = array();
		$data['cyberpunks_option_color_palettes'] = array();
		$data['cyberpunks_option_value_palette_colors'] = array();
		$data['entry_cyberpunks_color_palettes'] = $this->language->get('entry_cyberpunks_color_palettes');
		$data['entry_cyberpunks_palette_color'] = $this->language->get('entry_cyberpunks_palette_color');
		$data['text_cyberpunks_palette_none'] = $this->language->get('text_cyberpunks_palette_none');
		$data['help_cyberpunks_color_palettes'] = $this->language->get('help_cyberpunks_color_palettes');

		if (is_file(DIR_APPLICATION . 'model/extension/module/cyberpunks_shop_color_palettes.php')) {
			$this->load->model('extension/module/cyberpunks_shop_color_palettes');
			$this->model_extension_module_cyberpunks_shop_color_palettes->install();
			$data['cyberpunks_color_palettes'] = $this->model_extension_module_cyberpunks_shop_color_palettes->getOptionFormPalettes(true);

			if (isset($this->request->post['cyberpunks_option_color_palettes']) && is_array($this->request->post['cyberpunks_option_color_palettes'])) {
				$data['cyberpunks_option_color_palettes'] = array_map('intval', $this->request->post['cyberpunks_option_color_palettes']);
			} elseif (!empty($option_info) && isset($option_info['option_id'])) {
				$data['cyberpunks_option_color_palettes'] = $this->model_extension_module_cyberpunks_shop_color_palettes->getOptionPaletteIds((int)$option_info['option_id']);
			}

			if (isset($this->request->post['option_value']) && is_array($this->request->post['option_value'])) {
				foreach ($this->request->post['option_value'] as $cyberpunks_palette_row => $cyberpunks_palette_option_value) {
					$data['cyberpunks_option_value_palette_colors'][(int)$cyberpunks_palette_row] = isset($cyberpunks_palette_option_value['palette_color_id']) ? (int)$cyberpunks_palette_option_value['palette_color_id'] : 0;
				}
			} elseif (!empty($option_info) && isset($option_info['option_id'])) {
				$data['cyberpunks_option_value_palette_colors'] = $this->model_extension_module_cyberpunks_shop_color_palettes->getOptionValuePaletteColors((int)$option_info['option_id']);
			}
		}

		$data['cyberpunks_color_palettes_json'] = json_encode($data['cyberpunks_color_palettes'], JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE);

{% if cyberpunks_color_palettes %}
<div class="form-group">
  <label class="col-sm-2 control-label">{{ entry_cyberpunks_color_palettes }}</label>
  <div class="col-sm-10">
    <p class="help-block">{{ help_cyberpunks_color_palettes }}</p>
    {% for palette in cyberpunks_color_palettes %}
    <label class="checkbox-inline">
      <input type="checkbox" class="cyberpunks-option-palette-toggle" name="cyberpunks_option_color_palettes[]" value="{{ palette.palette_id }}" {% if palette.palette_id in cyberpunks_option_color_palettes %}checked="checked"{% endif %} />
      {{ palette.name }}
    </label>
    {% endfor %}
  </div>
</div>
{% endif %}

{% if cyberpunks_color_palettes %}
<td class="text-left cyberpunks-palette-color-column">{{ entry_cyberpunks_palette_color }}</td>
{% endif %}

{% if cyberpunks_color_palettes %}
{% set palette_color_id = 0 %}
{% if option_value.option_value_id is defined and cyberpunks_option_value_palette_colors[option_value.option_value_id] is defined %}
{% set palette_color_id = cyberpunks_option_value_palette_colors[option_value.option_value_id] %}
{% elseif cyberpunks_option_value_palette_colors[option_value_row] is defined %}
{% set palette_color_id = cyberpunks_option_value_palette_colors[option_value_row] %}
{% endif %}
<td class="text-left cyberpunks-palette-color-column">
  <select name="option_value[{{ option_value_row }}][palette_color_id]" class="form-control cyberpunks-palette-color-select" data-option-value-row="{{ option_value_row }}">
    <option value="0">{{ text_cyberpunks_palette_none }}</option>
    {% for palette in cyberpunks_color_palettes %}
      {% if palette.palette_id in cyberpunks_option_color_palettes %}
        {% for color in palette.colors %}
        <option value="{{ color.color_id }}" data-palette-id="{{ palette.palette_id }}" data-color-name="{{ color.name }}" {% if palette_color_id == color.color_id %}selected="selected"{% endif %}>{{ palette.name }} — {{ color.name }}</option>
        {% endfor %}
      {% endif %}
    {% endfor %}
  </select>
</td>
{% endif %}

{% if cyberpunks_color_palettes %}
var cyberpunksColorPalettes = {{ cyberpunks_color_palettes_json|raw }};
var cyberpunksSelectedPaletteIds = {{ cyberpunks_option_color_palettes|json_encode|raw }};

function cyberpunksBuildPaletteColorSelect(row) {
  var html = '  <td class="text-left cyberpunks-palette-color-column"><select name="option_value[' + row + '][palette_color_id]" class="form-control cyberpunks-palette-color-select" data-option-value-row="' + row + '">';
  html += '<option value="0">{{ text_cyberpunks_palette_none|e('js') }}</option>';

  cyberpunksColorPalettes.forEach(function(palette) {
    if (cyberpunksSelectedPaletteIds.indexOf(parseInt(palette.palette_id, 10)) === -1) {
      return;
    }

    (palette.colors || []).forEach(function(color) {
      html += '<option value="' + color.color_id + '" data-palette-id="' + palette.palette_id + '" data-color-name="' + String(color.name).replace(/"/g, '&quot;') + '">' + palette.name + ' — ' + color.name + '</option>';
    });
  });

  html += '</select></td>';
  return html;
}

function cyberpunksRefreshPaletteColorSelect($select) {
  var currentValue = $select.val();
  var row = $select.data('option-value-row');
  var html = '<option value="0">{{ text_cyberpunks_palette_none|e('js') }}</option>';

  cyberpunksColorPalettes.forEach(function(palette) {
    if ($('.cyberpunks-option-palette-toggle[value="' + palette.palette_id + '"]').is(':checked')) {
      (palette.colors || []).forEach(function(color) {
        html += '<option value="' + color.color_id + '" data-palette-id="' + palette.palette_id + '" data-color-name="' + String(color.name).replace(/"/g, '&quot;') + '">' + palette.name + ' — ' + color.name + '</option>';
      });
    }
  });

  $select.html(html);

  if (currentValue && $select.find('option[value="' + currentValue + '"]').length) {
    $select.val(currentValue);
  } else {
    $select.val('0');
  }
}

function cyberpunksApplyPaletteColorName($select) {
  var colorName = $select.find('option:selected').data('color-name');

  if (!colorName) {
    return;
  }

  var row = $select.data('option-value-row');
  $('input[name^="option_value[' + row + '][option_value_description]"][name$="[name]"]').val(colorName);
}

$(document).on('change', '.cyberpunks-option-palette-toggle', function() {
  cyberpunksSelectedPaletteIds = $('.cyberpunks-option-palette-toggle:checked').map(function() {
    return parseInt($(this).val(), 10);
  }).get();

  $('.cyberpunks-palette-color-select').each(function() {
    cyberpunksRefreshPaletteColorSelect($(this));
  });
});

$(document).on('change', '.cyberpunks-palette-color-select', function() {
  cyberpunksApplyPaletteColorName($(this));
});

$('.cyberpunks-palette-color-select').each(function() {
  cyberpunksApplyPaletteColorName($(this));
});
{% endif %}

$_['entry_cyberpunks_color_palettes'] = 'Color palettes';
$_['entry_cyberpunks_palette_color'] = 'Palette color';
$_['text_cyberpunks_palette_none'] = '— none —';
$_['help_cyberpunks_color_palettes'] = 'Attach one or more palettes. Option values can then pick a palette color instead of typing hex codes manually.';
